import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const f=JSON.parse('{"title":"Frequently asked questions","description":"","frontmatter":{"pageId":"faq","contentRevision":1},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md"}'),r={name:"en/faq.md"};function s(i,e,l,d,u,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p><strong>Must everyone play together?</strong> Not for independent colonies or asynchronous economy; yes for live and coop.</p><p><strong>Can I continue offline?</strong> Canonical state belongs to the server. Do not substitute a local save: it may conflict with items and transactions already settled.</p><p><strong>Where is a transfer after a disconnect?</strong> Reconnect and inspect mail, market and operation state first. The outbox retries an unanswered request with the same identifier.</p><p><strong>Does an alliance color mean territorial ownership?</strong> No. It is an informational overlay of voluntarily published influence.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Deleting journals or manually duplicating transfers can cause loss or duplication. Give an administrator the operation ID and time, never a password or token.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./players/saves-recovery">Saves and recovery</a></li><li><a href="./players/troubleshooting">Player troubleshooting</a></li><li><a href="./players/guild-influence">Guild influence</a></li></ul>',11)])])}const h=a(r,[["render",s]]);export{f as __pageData,h as default};
